// 【排好再用】
// 把一串数排好，再用排好的结果做一件有意思的事。主题你自己定。
// 先做到：用冒泡排序排好一串数，输出排好的样子。
// 选你喜欢的：跳远前三名、零花钱从少到多、最矮和最高、
//   去掉最高最低分，都可以。
// 还想更厉害：排一叠 Record 卡片，输出一张排行榜。
// ↓ 从这里开始造

#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;
    int a[20] = {};
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    return 0;
}
